"""Build the declarative method catalogue; acceptance status is explicit."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def p(label,kind,default,**kw):return dict(label=label,type=kind,default=default,**kw)
def enum(label,default,choices):return p(label,'enum',default,choices=[dict(id=a,label=b) for a,b in choices])
def rec(identity,label,description,parameters=None,stage='B',cost='Increases with data size and number of folds.'):
    return dict(id=identity,label=label,description=description,parameters=parameters or {},stage=stage,enabled=False,status='acceptance_pending' if stage=='B' else 'not_implemented',reason='Acceptance tests are in progress.' if stage=='B' else 'This stage is not implemented yet.',cost=cost)

def main():
    cats={}
    validation_params={'n_splits':p('Number of outer folds','int',5,min=2,max=50),'inner_splits':p('Number of inner folds','int',3,min=2,max=20),'repeats':p('Number of repeats','int',1,min=1,max=100),'seed':p('Random seed','int',42,min=0,max=2147483646),'block_size':p('Block size (m)','float',1000,min=1,max=1000000),'buffer_distance':p('Buffer distance (m)','float',0,min=0,max=1000000),'metric_crs':p('Metric coordinate reference system','string',''),'min_train_groups':p('Minimum training groups','int',2,min=2,max=10000),'inner_method':enum('Inner split for user-defined folds','group',[('group','Grouped'),('random','Random'),('spatial_block','Spatial block'),('buffered','Buffered')])}
    cats['validation']=[rec(i,l,d,validation_params) for i,l,d in [('random','Random k-fold','Does not separate dependent groups; for such data, choose the grouped method.'),('repeated','Repeated random k-fold','Each repeat is evaluated separately; the number of predictions is not the number of independent samples.'),('group','Grouped k-fold','Observations linked by profile, parcel and farm relationships are kept together.'),('spatial_block','Spatial block','Metric grid blocks are assigned to folds. This is not an unbiased estimate of map accuracy.'),('buffered','Buffered spatial','Training groups closer to the test blocks than the buffer distance are removed.'),('custom','User-defined folds','ID coverage, group and distance conditions are still checked.')]]
    cats['validation'] += [rec('knndm','k-fold nearest neighbor distance matching (kNNDM)','Requires comparison with the original CAST implementation.',stage='C'),rec('environmental','Environmental clusters','Environmental transfer must be tested separately.',stage='C'),rec('temporal','Temporal split','Dates and the forward-in-time task are validated separately.',stage='D'),rec('design_based','Design-based map validation (probability sample)','A weighted estimator that matches the sampling design is not implemented yet.',stage='separate')]
    cats['preprocessing']=[rec('standard_pipeline','Preprocessing','Each step is learned only from the relevant training observations.',{'imputation':enum('Missing inputs','median',[('none','None'),('median','Median'),('knn','Nearest neighbors')]),'scaling':enum('Scaling','standard',[('none','None'),('standard','Standard'),('robust','Robust')]),'unknown_category':enum('Unknown category','flag',[('error','Stop'),('flag','Flag')]),'knn_neighbors':p('Number of neighbors','int',5,min=1,max=100)})]
    cats['target_transform']=[rec('none','No transformation','Training in the original target unit.'),rec('log','Log transformation','Positive targets only. The back-transformed quantity is chosen in advance.',{'log_estimand':enum('Mapped quantity','median',[('median','Exponential back-transformation'),('mean_smearing','Mean correction from training residuals (smearing)')])}),rec('yeo_johnson','Yeo-Johnson transformation','The transformation coefficient is learned from training data only.')]
    vp={'threshold':p('Elimination threshold','float',10,min=1.01,max=100000),'protected_ids':p('Variable IDs to keep','ids',[]),'priority_ids':p('Variable IDs to eliminate first','ids',[])}
    cats['vif']=[rec('off','Off','Multicollinearity is not diagnosed.'),rec('diagnostic','Diagnostic only','The variance inflation factor (VIF) measures collinearity among covariates. It does not eliminate variables.',vp),rec('iterative','Iterative elimination','Continuous variables that exceed the threshold are eliminated one at a time within training. Categorical indicator columns are not split up.',vp)]
    selectors=[('none','No selection','Uses all selected inputs.'),('pearson','Pearson filter','Eliminates highly linearly correlated variables on training data.'),('spearman','Spearman filter','Evaluates rank correlation on training data.'),('mutual_info','Mutual information','Measures the nonlinear dependence between an input and the target soil property on training data.'),('elastic_net','Elastic Net selection','The linear selector model is separate from the final model.'),('sfs','Sequential forward selection','Preprocessing is relearned in each subfold. The computational cost is high.'),('rfe','Recursive feature elimination','Requires a model that provides coefficients or tree importance.'),('boruta','Boruta','Searches for relevant variables. It does not guarantee the smallest best model.'),('pca','Principal component analysis (PCA)','A transformation learned on training data; it is not variable selection.')]
    sp={'k':p('Number of variables / components','int',1,min=1,max=256),'threshold':p('Correlation threshold','float',0.9,min=0.01,max=1),'protected_ids':p('IDs to keep','ids',[]),'priority_ids':p('Elimination priority','ids',[])}
    sp['compare_without_selection']=p('Compare with the counterpart without selection','bool',False)
    cats['feature_selection']=[rec(i,l,d,{} if i=='none' else sp) for i,l,d in selectors]
    tree={'n_estimators':p('Number of trees','int',100,min=10,max=2000),'max_depth':p('Maximum depth','int',10,min=1,max=100),'min_samples_leaf':p('Minimum samples per leaf','int',2,min=1,max=100),'max_features':p('Fraction of variables','float',1.0,min=0.01,max=1)}
    cats['model']=[rec('mean','Training mean','Uses the training target mean as a comparator.'),rec('median','Training median','Uses the training target median as a comparator.'),rec('ridge','Ridge regression','Linear regression that shrinks the coefficients.',{'alpha':p('Regularization coefficient','float',1,min=0.000001,max=1000000)}),rec('elastic_net','Elastic Net regression','Combines two regularization penalties.',{'alpha':p('Regularization coefficient','float',1,min=0.000001,max=1000000),'l1_ratio':p('Share of the first penalty','float',0.5,min=0,max=1),'max_iter':p('Maximum iterations','int',10000,min=100,max=100000)}),rec('random_forest','Random forest','Builds an ensemble of trees from training samples.',tree),rec('extra_trees','Extremely randomized trees','Builds an ensemble of trees with random split points.',tree),rec('svr','Support vector regression','Kernel-based regression. Costly for large samples.',{'C':p('Penalty coefficient','float',1,min=0.000001,max=1000000),'epsilon':p('Error tolerance','float',0.1,min=0,max=10000),'kernel':enum('Kernel','rbf',[('rbf','Radial'),('linear','Linear')]),'gamma':enum('Kernel scale','scale',[('scale','Based on variance'),('auto','Based on number of variables')])}),rec('hist_gradient_boosting','Histogram-based gradient boosting','Early stopping is off; the number of iterations is chosen in inner folds.',{'max_iter':p('Iterations','int',100,min=10,max=2000),'max_leaf_nodes':p('Number of leaves','int',31,min=2,max=255),'learning_rate':p('Learning rate','float',0.1,min=0.0001,max=1),'min_samples_leaf':p('Minimum samples per leaf','int',10,min=1,max=100)}),rec('xgboost','XGBoost','Boosted trees on the CPU. Early stopping is off.',{'n_estimators':p('Number of trees','int',100,min=10,max=2000),'max_depth':p('Depth','int',6,min=1,max=20),'learning_rate':p('Learning rate','float',0.1,min=0.0001,max=1),'subsample':p('Fraction of observations','float',1,min=0.1,max=1),'colsample_bytree':p('Fraction of variables','float',1,min=0.1,max=1)})]
    for i,l in [('lightgbm','LightGBM'),('catboost','CatBoost'),('cubist','Cubist'),('ordinary_kriging','Ordinary kriging'),('regression_kriging','Regression kriging')]:cats['model'].append(rec(i,l,'Requires separate dependency and method acceptance.',stage='C'))
    for i,l in [('tabpfn','TabPFN'),('tabm','TabM'),('realmlp','RealMLP')]:cats['model'].append(rec(i,l,'Experimental model; license, version and local operation must be tested.',stage='D'))
    op={'trials':p('Trial budget','int',10,min=1,max=10000),'timeout_seconds':p('Time budget (s)','int',300,min=1,max=86400),'seed':p('Seed','int',42,min=0,max=2147483646),'metric':enum('Primary error metric','rmse',[('rmse','Root mean squared error (RMSE)'),('mae','Mean absolute error (MAE)')]),'n_jobs':p('Concurrent jobs','int',1,min=1,max=1)}
    cats['optimization']=[rec(i,l,d,op) for i,l,d in [('manual','Manual','Evaluates predefined settings in the same inner folds.'),('grid','Grid search','Evaluates all of a finite set of candidate settings within the budget.'),('random','Random search','Draws as many candidates from the defined ranges as the budget allows.'),('optuna','Optuna','The Tree-structured Parzen Estimator (TPE) chooses new settings based on previous trials. It does not guarantee the global best result.')]]
    up={'coverage':p('Nominal coverage','float',0.9,min=0.5,max=0.99),'calibration_fraction':p('Calibration fraction','float',0.25,min=0.05,max=0.5),'quantile_model':enum('Quantile model','quantile_forest',[('quantile_forest','Quantile regression forest'),('quantile_boosting','Gradient boosting with quantile loss')])}
    cats['uncertainty']=[rec(i,l,d,{} if i=='none' else up) for i,l,d in [('none','No interval','Point prediction only.'),('split_conformal','Split conformal','Builds intervals from the absolute errors of separate calibration observations.'),('quantile_forest','Quantile regression forest','True conditional quantiles in the random forest family. Coverage without calibration is tested in outer folds.'),('quantile_boosting','Gradient boosting with quantile loss','Separate lower and upper quantile models in the histogram-based gradient boosting family.'),('cqr','Conformalized quantile regression (CQR)','Adjusts the quantile interval with separate calibration data.')]]
    cats['uncertainty'] += [rec('group_bootstrap','Group bootstrap spread','This is modeling variability; it is not a prediction interval for observations.',stage='C'),rec('spatial_conformal','Advanced spatial conformal','Requires method-specific assumptions and separate acceptance.',stage='D')]
    obj={'schema_version':1,'registry_version':'0.2.0-dev','categories':cats}
    dest=ROOT/'backend/sps/registry.json';dest.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(dest)
if __name__=='__main__':main()
